  DFW: {name: Dallas, lat: 32.90, lon: -97.04, metro_m: 8.1, site: 11, runway_ft: 13400}
  ABQ: {name: Albuquerque, lat: 35.04, lon: -106.61, metro_m: 0.9, site: 12, runway_ft: 13800}
